    {
      "op": "add_linear_dim",
      "category": "annotate",
      "description": "Linear dimension between two points. orientation: horizontal | vertical | aligned | rotated. The dimension line is placed at 'base' or at 'offset' from the measured points.",
      "params": {
        "type": "object",
        "properties": {
          "p1": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "First extension line origin [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "p2": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Second extension line origin [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "orientation": {
            "type": "string",
            "enum": [
              "horizontal",
              "vertical",
              "aligned",
              "rotated"
            ],
            "description": "",
            "default": "horizontal"
          },
          "angle": {
            "type": "number",
            "description": "Measurement direction for orientation=rotated (degrees, counter-clockwise)",
            "default": 0.0
          },
          "offset": {
            "type": [
              "number",
              "string"
            ],
            "description": "Distance of the dimension line from the points (sign = side) (drawing units, or string with unit e.g. '8mm')",
            "default": 10.0
          },
          "base": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Explicit location of the dimension line [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "text": {
            "type": "string",
            "description": "Text override; '<>' stands for the measured value"
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Override text height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "length_factor": {
            "type": "number",
            "description": "DIMLFAC: displayed value = measured length x factor, e.g. 1/0.325 on a sheet that shows the part at scale 0.325",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "p1",
          "p2"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "create_layer",
      "category": "layer",
      "description": "Create a layer (no-op with if_exists='skip').",
      "params": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": ""
          },
          "color": {
            "type": "integer",
            "description": "ACI color",
            "minimum": 1,
            "maximum": 255,
            "default": 7
          },
          "linetype": {
            "type": "string",
            "description": "",
            "default": "Continuous"
          },
          "lineweight": {
            "type": "integer",
            "description": "1/100 mm, -3 = default",
            "default": -3
          },
          "if_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "update"
            ],
            "description": "",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_polyline",
      "category": "draw",
      "description": "Draw a 2D polyline (LWPOLYLINE). Points may carry a bulge as third value (bulge = tan(arc_angle/4), positive = CCW arc to the next vertex).",
      "params": {
        "type": "object",
        "properties": {
          "points": {
            "type": "array",
            "items": {
              "type": "array"
            },
            "description": "Vertices list of [x, y] (or [x, y, bulge]) (drawing units, or string with unit e.g. '8mm')"
          },
          "closed": {
